package dev.nexus.client.render;

/**
 * Icons packed into {@code assets/nexus/textures/gui/icons.png} (8 columns, 40px cells, 32px glyph).
 * The atlas is generated by {@code tools/gen_icons.py}; order must match.
 */
public enum Icon {
    LOGO, HOME, MODULES, HUD, PROFILES, SETTINGS, INFO, SEARCH,
    EYE, MONITOR, LAYOUT, WRENCH, BOLT, CLOSE, BACK, CHEVRON_RIGHT,
    CHEVRON_DOWN, CHECK, PLUS, TRASH, EDIT, REFRESH, KEYBOARD, SUN,
    MOON, POWER, RESET, COPY, GRID, MAGNET, FOLDER, MOVE;

    public static final int COLUMNS = 8;
    public static final int CELL = 40;
    public static final int GLYPH = 32;
    public static final int PADDING = (CELL - GLYPH) / 2;
    public static final int ATLAS_WIDTH = COLUMNS * CELL;
    public static final int ATLAS_HEIGHT = 4 * CELL;

    public int u() {
        return (ordinal() % COLUMNS) * CELL + PADDING;
    }

    public int v() {
        return (ordinal() / COLUMNS) * CELL + PADDING;
    }
}
